ttle, WA 98122","nhood":"Capitol Hill","cat":"Bar","phone":null,"web":null},{"id":"4c7f1110-7af2-562d-9fa2-e0aa57dc496a","name":"Seattle Hookah Lounge","lat":47.663269,"lng":-122.317646,"addr":"4701 Roosevelt Way Northeast, Seattle, WA 98105","nhood":"University District","cat":"Lounge","phone":null,"web":null},{"id":"7d0b3922-73fb-5f52-beed-1e9504342113","name":"Shadowland","lat":47.562987,"lng":-122.386586,"addr":"4458 California Avenue Southwest, Seattle, WA 98116","nhood":"West Seattle","cat":"Bar","phone":null,"web":null},{"id":"8bcbd8ea-51b4-5bd0-9d6b-213a4540d0cb","name":"Shanghai Room","lat":47.692204,"lng":-122.355109,"addr":"8580 Greenwood Avenue North, Seattle, WA 98103","nhood":"Greenwood","cat":"Bar","phone":null,"web":"https://www.theshanghairoom.com/"},{"id":"50c186a3-254a-5f90-af3d-7664e9556470","name":"Shibuya Hifi","lat":47.664558,"lng":-122.379251,"addr":"4912 Leary Avenue Northwest, Seattle, WA 98107","nhood":"Ballard","cat":"Bar","phone":null,"web":"https://www.shibuyahifi.com/"},{"id":"d536e4cd-497c-566d-9e1f-8f1fb1903deb","name":"Siren Tavern","lat":47.573496,"lng":-122.329538,"addr":"3403 4th Avenue South, Seattle, WA 98134","nhood":"SoDo","cat":"Bar","phone":"+1-206-223-9167","web":null}]'::jsonb)
  AS x(id uuid, name text, lat float, lng float, addr text, nhood text, cat text, phone text, web text)
), updated AS (
  UPDATE venues v SET
    name = c.name, location_lat = c.lat, location_lng = c.lng, location_address = c.addr,
    city = 'Seattle', state = 'WA', neighborhood = COALESCE(c.nhood, v.neighborhood), category = c.cat,
    seeded = true, inventory_source = 'osm', phone = c.phone, website = c.web,
    pulse_score = CASE WHEN v.last_pulse_at IS NULL THEN 0 ELSE v.pulse_score END,
    score_velocity = CASE WHEN v.last_pulse_at IS NULL THEN 0 ELSE v.score_velocity END
  FROM catalog c
  WHERE v.deleted_at IS NULL AND v.inventory_source IS DISTINCT FROM 'curated-seed'
    AND (v.id = c.id OR (lower(v.name) = lower(c.name) AND lower(v.location_address) = lower(c.addr) AND v.city = 'Seattle' AND v.state = 'WA'))
  RETURNING v.id
)
INSERT INTO venues (id, name, location_lat, location_lng, location_address, city, state, neighborhood, category, pulse_score, score_velocity, seeded, inventory_source, phone, website)
SELECT c.id, c.name, c.lat, c.lng, c.addr, 'Seattle', 'WA', c.nhood, c.cat, 0, 0, true, 'osm', c.phone, c.web
FROM catalog c
WHERE NOT EXISTS (
  SELECT 1 FROM venues v WHERE v.id = c.id OR (lower(v.name) = lower(c.name) AND lower(v.location_address) = lower(c.addr) AND v.city = 'Seattle' AND v.state = 'WA')
);
